# M9 field evidence intake for local-only Windows execution.
# Forms generated by -Mode kit are BLANK and cannot certify field measurement.
[CmdletBinding()]
param(
  [ValidateSet("plan","kit","hashes","check")][string]$Mode="plan",
  [string]$Workdir=".streetlab-m5",
  [Parameter(Mandatory=$true)][string]$Project,
  [string]$Python="",
  [string]$OutputDir="",
  [string]$FieldDir=""
)
Set-StrictMode -Version Latest
$ErrorActionPreference="Stop"
$repo=(Resolve-Path (Join-Path $PSScriptRoot "..")).Path
Set-Location $repo
if ([string]::IsNullOrWhiteSpace($Python)) {
  $Python=Join-Path $repo ".venv-sahi-audit\Scripts\python.exe"
}
if (-not (Test-Path -LiteralPath $Python -PathType Leaf)) {
  throw "Supply the verified Python virtual environment using -Python"
}
if (-not [System.IO.Path]::IsPathRooted($Workdir)) {
  $Workdir=Join-Path $repo $Workdir
}
$Arguments=@("-m","streetlab_integration.fieldwork","--workdir",$Workdir,"--project",$Project)
switch($Mode) {
  "plan" { $Arguments+="--plan" }
  "kit" {
    if ([string]::IsNullOrWhiteSpace($OutputDir)) {
      throw "Provide a NEW output folder using -OutputDir; originals are never overwritten"
    }
    if (Test-Path -LiteralPath $OutputDir) {
      throw "Field kit output folder already exists; refusing overwrite"
    }
    $Arguments+=@("--init",$OutputDir)
  }
  "hashes" {
    if ([string]::IsNullOrWhiteSpace($FieldDir) -or
        -not (Test-Path -LiteralPath $FieldDir -PathType Container)) {
      throw "Provide an existing original record directory using -FieldDir"
    }
    $Arguments+=@("--hashes",$FieldDir)
  }
  "check" {
    if ([string]::IsNullOrWhiteSpace($FieldDir) -or
        -not (Test-Path -LiteralPath $FieldDir -PathType Container)) {
      throw "Provide an existing original record directory using -FieldDir"
    }
    $Arguments+=@("--check",$FieldDir)
  }
}
& $Python @Arguments
if ($LASTEXITCODE -ne 0) {exit $LASTEXITCODE}
